<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans;color:#17221c}h1{color:#176c4d}.head,.totals{display:flex;justify-content:space-between}.box{border:1px solid #ccd8d1;padding:18px;margin:20px 0}table{width:100%;border-collapse:collapse;margin:16px 0}th,td{text-align:left;padding:8px;border-bottom:1px solid #edf1ef;font-size:13px}.totals{font-size:18px;border-top:2px solid #176c4d;padding-top:14px}small{color:#66736c}</style></head><body><div class="head"><div><h1>{{ $invoice->company->name }}</h1><small>Invoice</small></div><div><strong>{{ $invoice->invoice_number }}</strong><br>{{ $invoice->period_start->format('d M Y') }} – {{ $invoice->period_end->format('d M Y') }}<br>@if($invoice->due_date)Due: {{ $invoice->due_date->format('d M Y') }}@endif</div></div><div class="box"><strong>{{ $invoice->customer->name }}</strong><br>{{ $invoice->customer->building->name }} / Room {{ $invoice->customer->room->number }}</div><table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Amount</th></tr></thead><tbody>@foreach($invoice->lines as $line)<tr><td>{{ $line->description }}</td><td>{{ $line->quantity }}</td><td>{{ number_format($line->unit_price,2) }}</td><td>{{ number_format($line->amount,2) }}</td></tr>@endforeach</tbody></table><p>Previous balance: {{ $invoice->company->currency }} {{ number_format($invoice->previous_balance,2) }}<br>Current charges: {{ $invoice->company->currency }} {{ number_format($invoice->current_charges,2) }}<br>Amount paid: {{ $invoice->company->currency }} {{ number_format($invoice->amount_paid,2) }}</p><div class="totals"><span>Balance due</span><strong>{{ $invoice->company->currency }} {{ number_format($invoice->balance,2) }}</strong></div></body></html>
